import { NextResponse } from "next/server";
import { writeFile, unlink } from "fs/promises";
import path from "path";
import { execFile } from "child_process";
import { promisify } from "util";

const execFileAsync = promisify(execFile);

export async function POST(request) {
  let imagePath = null;

  try {
    const body = await request.json();

    if (!body.image) {
      return NextResponse.json(
        { error: "No image provided" },
        { status: 400 }
      );
    }

    // Remove base64 header
    const base64Data = body.image.replace(
      /^data:image\/\w+;base64,/,
      ""
    );

    // Convert base64 → image buffer
    const imageBuffer = Buffer.from(
      base64Data,
      "base64"
    );

    // Temporary image path
    imagePath = path.join(
      process.cwd(),
      "temp-plant-image.jpg"
    );

    await writeFile(
      imagePath,
      imageBuffer
    );

    // Location of medicinal_plant_model
    const modelDir = path.join(
      process.cwd(),
      "..",
      "medicinal_plant_model"
    );

    const pythonScript = path.join(
      modelDir,
      "predict.py"
    );

    console.log("Running Python model...");

    // Run Python
    const { stdout, stderr } =
      await execFileAsync(
        "python",
        [
          pythonScript,
          imagePath
        ],
        {
          cwd: modelDir,
        }
      );

    console.log("Python output:", stdout);

    if (stderr) {
      console.log(
        "Python stderr:",
        stderr
      );
    }

    // Convert Python JSON → JS object
    const result = JSON.parse(
      stdout.trim()
    );

    return NextResponse.json({
      plant: result.plant,
      confidence: result.confidence,
      properties:
        result.properties ||
        "Plant identified successfully."
    });

  } catch (error) {

    console.error(
      "Prediction error:",
      error
    );

    return NextResponse.json(
      {
        error:
          error.message ||
          "Prediction failed"
      },
      {
        status: 500
      }
    );

  } finally {

    // Delete temporary image
    if (imagePath) {
      try {
        await unlink(imagePath);
      } catch {}
    }

  }
}